class Solution:
    def maximumNumber(self, num: str, change: List[int]) -> str:
        best = num
        n = len(num)
        for i in range(n):
            cur = list(num)
            for j in range(i, n):
                cur[j] = str(change[int(num[j])])
                cand = "".join(cur)
                if cand > best:
                    best = cand
        return best

