class Solution {
public:
    string maximumNumber(string num, vector<int>& change) {
        int n = num.size();
        string best = num;
        for (int i = 0; i < n; i++) {
            string cur = num;
            for (int j = i; j < n; j++) {
                cur[j] = char('0' + change[num[j] - '0']);
                if (cur > best) best = cur;
            }
        }
        return best;
    }
};

