class Solution {
    public String maximumNumber(String num, int[] change) {
        int n = num.length();
        String best = num;
        for (int i = 0; i < n; i++) {
            char[] cur = num.toCharArray();
            for (int j = i; j < n; j++) {
                cur[j] = (char) ('0' + change[cur[j] - '0']);
                String cand = new String(cur);
                if (cand.compareTo(best) > 0) best = cand;
            }
        }
        return best;
    }
}

